//! `DateTime` / `DateTimeImmutable` construction, `date_create()`, `createFromFormat()` and `getLastErrors()`
//! against PHP 8.5.13 with a faked clock (`tests/vectors/construct.json`, generated by `construct.gen.php`;
//! regenerate with `crates/twig-date/tests/vectors/regen.sh construct`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::{DateObject, TimeZoneObject, classes, datetime};
use twig_value::object::ClassRef;

fn class(name: &str) -> ClassRef {
    match name {
        "DateTime" => classes::datetime(),
        "DateTimeImmutable" => classes::datetime_immutable(),
        other => panic!("class {other}"),
    }
}

fn setup(c: &Ctx, default: &str, sec: &Json, usec: &Json) {
    assert!(
        c.ctx
            .default_timezone_set(default.as_bytes(), &mut Vec::new())
            .unwrap()
    );
    c.now(i(sec), i(usec));
}

fn tz(c: &Ctx, v: &Json) -> Option<twig_value::ObjectRef> {
    v.as_str()
        .map(|z| TimeZoneObject::construct(&c.ctx, z.as_bytes()).unwrap())
}

#[test]
fn construction() {
    let v = load("construct");
    let c = Ctx::new();
    let mut r = Report::new("new DateTime()");
    for case in v["construct"].as_array().unwrap() {
        let input = bytes(&case[1]);
        setup(&c, s(&case[3]), &case[4], &case[5]);
        let tz = tz(&c, &case[2]);
        let got = match DateObject::construct(&c.ctx, class(s(&case[0])), &input, tz.as_ref()) {
            Ok(d) => result(&d),
            Err(e) => exc(&e),
        };
        let errors = to_json(&datetime::last_errors_value(&c.ctx));
        let what = || format!("{case}");
        r.eq(got, s(&case[6]).to_owned(), what);
        r.eq(errors, case[7].clone(), || format!("last errors of {case}"));
    }
    r.finish();
}

#[test]
fn date_create() {
    let v = load("construct");
    let c = Ctx::new();
    let mut r = Report::new("date_create()");
    for case in v["create"].as_array().unwrap() {
        let input = bytes(&case[1]);
        setup(&c, s(&case[3]), &case[4], &case[5]);
        let tz = tz(&c, &case[2]);
        let got = match twig_date::functions::date_create(&c.ctx, &input, tz.as_ref()).unwrap() {
            Some(d) => Json::String(result(&d)),
            None => Json::Bool(false),
        };
        r.eq(got, case[6].clone(), || format!("{case}"));
        let errors = to_json(&datetime::last_errors_value(&c.ctx));
        r.eq(errors, case[7].clone(), || format!("last errors of {case}"));
    }
    r.finish();
}

#[test]
fn create_from_format() {
    let v = load("construct");
    let c = Ctx::new();
    let mut r = Report::new("createFromFormat()");
    for case in v["format"].as_array().unwrap() {
        let (format, input) = (bytes(&case[1]), bytes(&case[2]));
        setup(&c, s(&case[4]), &case[5], &case[6]);
        let tz = tz(&c, &case[3]);
        let got = match DateObject::create_from_format(
            &c.ctx,
            class(s(&case[0])),
            &format,
            &input,
            tz.as_ref(),
        )
        .unwrap()
        {
            Some(d) => Json::String(result(&d)),
            None => Json::Bool(false),
        };
        r.eq(got, case[7].clone(), || format!("{case}"));
        let errors = to_json(&datetime::last_errors_value(&c.ctx));
        r.eq(errors, case[8].clone(), || format!("last errors of {case}"));
    }
    r.finish();
}
